package com.drops.pos;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.*;import android.graphics.Typeface;import android.view.*;import android.widget.*;import java.util.*;

public class MainActivity extends Activity{
 DB db; LinearLayout root,body; final int NAVY=0xff0f172a,BLUE=0xff2563eb,BG=0xfff5f7fa;
 int dp(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}
 TextView t(String s,int z,int c,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(dp(14),dp(10),dp(14),dp(10));if(b)v.setTypeface(null,Typeface.BOLD);return v;}
 public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);home();}
 void shell(String p,String sub){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout h=new LinearLayout(this);h.setOrientation(LinearLayout.VERTICAL);h.setBackgroundColor(NAVY);h.setPadding(dp(10),dp(12),dp(10),dp(10));h.addView(t("DROPS POS  •  "+p,22,Color.WHITE,true));h.addView(t(sub,12,0xffcbd5e1,false));root.addView(h);ScrollView sv=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(12),dp(12),dp(12),dp(80));sv.addView(body);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));LinearLayout n=new LinearLayout(this);n.setBackgroundColor(Color.WHITE);nav(n,"الرئيسية",()->home());nav(n,"بيع",()->pos());nav(n,"المنتجات",()->products());nav(n,"التقارير",()->reports());root.addView(n,new LinearLayout.LayoutParams(-1,dp(62)));setContentView(root);}
 void nav(LinearLayout n,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(11);b.setOnClickListener(v->r.run());n.addView(b,new LinearLayout.LayoutParams(0,-1,1));}
 void card(String a,String b,String c){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setBackgroundColor(Color.WHITE);x.addView(t(a,13,0xff64748b,false));x.addView(t(b,24,NAVY,true));x.addView(t(c,12,0xff64748b,false));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(9));body.addView(x,lp);}
 void btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());body.addView(b,new LinearLayout.LayoutParams(-1,dp(56)));}
 void home(){shell("لوحة التحكم","بيانات محفوظة على الجهاز • USD / LBP");card("مبيعات اليوم","$ "+fmt(db.todaySales()),db.todayCount()+" فاتورة");card("قيمة المخزون","$ "+fmt(db.stockValue()),db.productCount()+" منتج");card("تنبيه المخزون",""+db.lowCount(),"منتجات وصلت إلى 5 قطع أو أقل");btn("＋ فاتورة بيع جديدة",()->pos());btn("＋ إضافة منتج",()->productDialog());btn("إدخال مخزون",()->stockIn());btn("المصاريف",()->expenses());}
 void products(){shell("المنتجات","السعر والكمية يتحدثان فعلياً");Cursor c=db.getProducts();while(c.moveToNext()){final long id=c.getLong(0);String name=c.getString(1),size=c.getString(2);double price=c.getDouble(3);int qty=c.getInt(4);card(name+" • "+size,"$ "+fmt(price),"Stock: "+qty);btn("تعديل / إضافة كمية — "+name,()->editProduct(id));}c.close();btn("＋ منتج جديد",()->productDialog());}
 void productDialog(){LinearLayout l=form();EditText n=e("اسم المنتج"),s=e("الحجم مثال 1L"),p=e("سعر البيع USD"),q=e("الكمية");l.addView(n);l.addView(s);l.addView(p);l.addView(q);new AlertDialog.Builder(this).setTitle("منتج جديد").setView(l).setPositiveButton("حفظ",(d,w)->{try{db.addProduct(n.getText().toString(),s.getText().toString(),Double.parseDouble(p.getText().toString()),Integer.parseInt(q.getText().toString()));products();}catch(Exception ex){toast("راجع البيانات");}}).setNegativeButton("إلغاء",null).show();}
 void editProduct(long id){Cursor c=db.one(id);if(!c.moveToFirst())return;LinearLayout l=form();EditText p=e("السعر"),q=e("الكمية");p.setText(""+c.getDouble(3));q.setText(""+c.getInt(4));l.addView(p);l.addView(q);c.close();new AlertDialog.Builder(this).setTitle("تعديل المنتج").setView(l).setPositiveButton("حفظ",(d,w)->{try{db.updateProduct(id,Double.parseDouble(p.getText().toString()),Integer.parseInt(q.getText().toString()));products();}catch(Exception x){toast("راجع البيانات");}}).setNegativeButton("إلغاء",null).show();}
 void stockIn(){Cursor c=db.getProducts();ArrayList<Long> ids=new ArrayList<>();ArrayList<String> names=new ArrayList<>();while(c.moveToNext()){ids.add(c.getLong(0));names.add(c.getString(1)+" "+c.getString(2));}c.close();if(ids.size()==0){toast("أضف منتج أولاً");return;}new AlertDialog.Builder(this).setTitle("اختر المنتج").setItems(names.toArray(new String[0]),(d,i)->qtyDialog(ids.get(i))).show();}
 void qtyDialog(long id){EditText q=e("الكمية الداخلة");new AlertDialog.Builder(this).setTitle("إدخال مخزون").setView(q).setPositiveButton("إضافة",(d,w)->{try{db.addStock(id,Integer.parseInt(q.getText().toString()));home();}catch(Exception x){toast("كمية غير صحيحة");}}).setNegativeButton("إلغاء",null).show();}
 void pos(){shell("نقطة البيع","اضغط المنتج لإتمام بيع قطعة واحدة");Cursor c=db.getProducts();while(c.moveToNext()){final long id=c.getLong(0);String name=c.getString(1)+" • "+c.getString(2);double price=c.getDouble(3);int qty=c.getInt(4);btn(name+"     $"+fmt(price)+"     ["+qty+"]",()->sell(id));}c.close();}
 void sell(long id){Cursor c=db.one(id);if(!c.moveToFirst())return;String name=c.getString(1)+" "+c.getString(2);double price=c.getDouble(3);int stock=c.getInt(4);c.close();if(stock<=0){toast("المخزون صفر");return;}LinearLayout l=form();EditText q=e("الكمية");q.setText("1");l.addView(q);new AlertDialog.Builder(this).setTitle("بيع "+name).setView(l).setPositiveButton("تأكيد البيع",(d,w)->{try{int z=Integer.parseInt(q.getText().toString());if(db.sell(id,z,price)){toast("تم حفظ البيع وخصم المخزون");pos();}else toast("الكمية غير متوفرة");}catch(Exception x){toast("كمية غير صحيحة");}}).setNegativeButton("إلغاء",null).show();}
 void expenses(){shell("المصاريف","تسجيل المصروفات اليومية");card("مصاريف اليوم","$ "+fmt(db.todayExpenses()),"محفوظة محلياً");btn("＋ تسجيل مصروف",()->expenseDialog());}
 void expenseDialog(){LinearLayout l=form();EditText n=e("البيان"),a=e("المبلغ USD");l.addView(n);l.addView(a);new AlertDialog.Builder(this).setTitle("مصروف جديد").setView(l).setPositiveButton("حفظ",(d,w)->{try{db.addExpense(n.getText().toString(),Double.parseDouble(a.getText().toString()));expenses();}catch(Exception x){toast("راجع المبلغ");}}).setNegativeButton("إلغاء",null).show();}
 void reports(){shell("التقارير","أرقام فعلية من قاعدة البيانات");double s=db.todaySales(),e=db.todayExpenses();card("مبيعات اليوم","$ "+fmt(s),db.todayCount()+" فاتورة");card("مصاريف اليوم","$ "+fmt(e),"مسجلة على الجهاز");card("صافي الحركة","$ "+fmt(s-e),"المبيعات ناقص المصاريف");card("قيمة المخزون","$ "+fmt(db.stockValue()),"حسب سعر البيع الحالي");}
 LinearLayout form(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(16),dp(4),dp(16),0);return l;} EditText e(String h){EditText x=new EditText(this);x.setHint(h);x.setPadding(dp(8),dp(10),dp(8),dp(10));return x;}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}String fmt(double d){return String.format(Locale.US,"%.2f",d);}
 static class DB extends SQLiteOpenHelper{DB(Context c){super(c,"drops.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,size TEXT,price REAL,qty INTEGER DEFAULT 0)");d.execSQL("CREATE TABLE sales(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER,qty INTEGER,total REAL,created INTEGER)");d.execSQL("CREATE TABLE expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,amount REAL,created INTEGER)");seed(d);}void seed(SQLiteDatabase d){String[][] a={{"Dishwashing","1L","2.56"},{"Dishwashing","4L","2.56"},{"Laundry Gel","1L","2.89"},{"Laundry Gel","4L","2.89"},{"Hand Soap","1L","3.11"},{"Hand Soap","4L","3.11"},{"Floor Cleaner","4L","2.22"}};for(String[]x:a)d.execSQL("INSERT INTO products(name,size,price,qty) VALUES(?,?,?,0)",x);}public void onUpgrade(SQLiteDatabase d,int a,int b){}
 Cursor getProducts(){return getReadableDatabase().rawQuery("SELECT * FROM products ORDER BY name,size",null);}Cursor one(long id){return getReadableDatabase().rawQuery("SELECT * FROM products WHERE id=?",new String[]{""+id});}
 void addProduct(String n,String s,double p,int q){ContentValues v=new ContentValues();v.put("name",n);v.put("size",s);v.put("price",p);v.put("qty",q);getWritableDatabase().insert("products",null,v);}void updateProduct(long id,double p,int q){ContentValues v=new ContentValues();v.put("price",p);v.put("qty",q);getWritableDatabase().update("products",v,"id=?",new String[]{""+id});}void addStock(long id,int q){getWritableDatabase().execSQL("UPDATE products SET qty=qty+? WHERE id=?",new Object[]{q,id});}
 boolean sell(long id,int q,double p){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{Cursor c=d.rawQuery("SELECT qty FROM products WHERE id=?",new String[]{""+id});c.moveToFirst();int st=c.getInt(0);c.close();if(q<=0||st<q)return false;d.execSQL("UPDATE products SET qty=qty-? WHERE id=?",new Object[]{q,id});d.execSQL("INSERT INTO sales(product_id,qty,total,created) VALUES(?,?,?,?)",new Object[]{id,q,p*q,System.currentTimeMillis()});d.setTransactionSuccessful();return true;}finally{d.endTransaction();}}
 void addExpense(String n,double a){getWritableDatabase().execSQL("INSERT INTO expenses(name,amount,created) VALUES(?,?,?)",new Object[]{n,a,System.currentTimeMillis()});}
 long start(){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}double scalar(String sql,String[]a){Cursor c=getReadableDatabase().rawQuery(sql,a);c.moveToFirst();double x=c.getDouble(0);c.close();return x;}double todaySales(){return scalar("SELECT COALESCE(SUM(total),0) FROM sales WHERE created>=?",new String[]{""+start()});}int todayCount(){return(int)scalar("SELECT COUNT(*) FROM sales WHERE created>=?",new String[]{""+start()});}double todayExpenses(){return scalar("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE created>=?",new String[]{""+start()});}double stockValue(){return scalar("SELECT COALESCE(SUM(price*qty),0) FROM products",null);}int productCount(){return(int)scalar("SELECT COUNT(*) FROM products",null);}int lowCount(){return(int)scalar("SELECT COUNT(*) FROM products WHERE qty<=5",null);}
 }
}